import type { ChunkData, MapIndex } from './MapTypes';

/** Source of processed map chunks. Swap implementations to change where data comes from. */
export interface MapDataProvider {
  loadIndex(): Promise<MapIndex>;
  loadChunk(key: string): Promise<ChunkData>;
}

/** Static pre-processed OSM chunks (generated by `npm run fetch-map`) served over HTTP. */
export class StaticChunkProvider implements MapDataProvider {
  constructor(private baseUrl: string) {}

  async loadIndex(): Promise<MapIndex> {
    return this.get(`${this.baseUrl}/index.json`);
  }

  async loadChunk(key: string): Promise<ChunkData> {
    return this.get(`${this.baseUrl}/chunks/${key}.json`);
  }

  private async get<T>(url: string): Promise<T> {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
    return res.json();
  }
}
